style.css:
@-moz-document domain("youtube.com") {
/* Hide default YouTube spinner */
  .ytp-spinner,
  .ytp-spinner-container,
  .ytp-spinner-svg,
  ytd-page-navigation-progress {
    display: none !important;
  }

  /* Add Maxwell's cat spinner over YouTube */
  html::before {
    content: "";
    position: fixed;
    top: 50%;
    left: 50%;
    width: 120px;
    height: 120px;
    margin-top: -60px;
    margin-left: -60px;
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/0/0a/Cat_March_2010-1a.jpg");
    background-size: cover;
    background-position: center;
    border-radius: 50%;
    z-index: 999999;
    animation: spinnycat 2s linear infinite;
    pointer-events: none;
  }

  @keyframes spinnycat {
    from {
      transform: rotate(0deg);
    }
    to {
      transform: rotate(360deg);
    }
  }
}
